// generated by wd.py: menu toggle, program tabs and room filter. Works without JS too (everything is visible).
(function(){
  document.documentElement.classList.add('js');
  var days=document.querySelectorAll('.program .day');
  if(days.length>1){days.forEach(function(d,i){d.hidden=i!==0;});}
  var t=document.querySelector('.nav-toggle'),n=document.querySelector('.nav');
  if(t&&n){t.addEventListener('click',function(){var o=n.classList.toggle('open');t.setAttribute('aria-expanded',o?'true':'false');});}
  var tabs=document.querySelectorAll('.program .tab');
  if(tabs.length){
    tabs.forEach(function(tab){tab.addEventListener('click',function(){
      tabs.forEach(function(x){x.classList.remove('active');x.setAttribute('aria-selected','false');});
      tab.classList.add('active');tab.setAttribute('aria-selected','true');
      document.querySelectorAll('.program .day').forEach(function(d){d.hidden=d.id!==tab.getAttribute('aria-controls');});
    });});
  }
  var f=document.getElementById('room-filter');
  if(f){f.addEventListener('change',function(){var v=f.value;document.querySelectorAll('.program .session').forEach(function(s){s.style.display=(!v||s.getAttribute('data-room')===v)?'':'none';});});}
})();
